// Universal reference: T&& used in a template context
template <typename T>
void sink(T&& t) { /* Implementation */ }

// Perfect Forwarding Wrapper
template <typename Arg>
void forwarder(Arg&& arg) {
    // std::forward maintains the original value category
    // T is the deduced type (e.g., int or int&)
    sink(std::forward<Arg>(arg));
}

struct Data {};
Data d;

forwarder(d);      // Arg deduced as Data& (Lvalue reference)
forwarder(Data{}); // Arg deduced as Data (Rvalue reference)

// Implementation relies on reference collapsing rules:
// T& && -> T&
// T&& && -> T&&
